# SdPowerCtrlSet  (CPU 0x4854c9a3)
#   IE-off: OR d0 into the shadow 0x5000520C -> 0x98060000, 10-count
#   settle spin.  0x98060000 is the sound-control latch IC25: bit0
#   USB.WAITM, bit1 SPSW, bit2 SDMODE, bits3-5 the D/A converter's
#   ML/MC/MDI (kn7000/notes/audio-mute-probes/README.md)
SdPowerCtrlSet:
    and     0xf7ff, psw
    nop
    nop
    movbu   (SdPowerCtrlSet_Table), d1
    extbu   d0
    or      d0, d1
    movbu   d1, (SdPowerCtrlSet_Table)
    movbu   (SdPowerCtrlSet_Table), d0
    movbu   d0, (SD_POWER_CTRL)
    or      0x0800, psw
    nop
    nop
    clr     d1
    setlb
    exthu   d0
    inc     d0
    inc     d1
    exthu   d1
    cmp     0xa, d1
    llt
    rets
# SdPowerCtrlClear  (CPU 0x4854c9d5)
